use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    var has_frame = true;
    var frame_opt = feed.next_frame();
    while has_frame {
        match frame_opt {
            Some(frame) => {
                let decoded = feed.decode(frame: frame);
                total = total + match decoded {
                    Some(value) => value,
                    None => 0,
                };
                frame_opt = feed.next_frame();
            },
            None => {
                has_frame = false;
            },
        };
    }
    feed.emit(total: total, io: io)?;
    return Ok(unit);
}

