use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = menu.board();
    var i = 0;
    let len = board.len();
    while i < len {
        if i > 0 {
            io.write(text: ";")?;
        }
        let dish = board[i];
        kitchen.serve(dish: dish, io: io)?;
        i = i + 1;
    }
    return Ok(unit);
}

