use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.inventory();
    let kept = planks.filter(plank => rules.keep(plank));
    let labels = kept.map(plank => rules.label(plank));
    labels.join(",")
}

fn lines() -> String {
    let planks = mill.stock.inventory();
    let mut result = "";
    let mut first = true;
    let mut i = 0;
    while i < planks.len() {
        let plank = planks.get(i);
        if mill.rules.keep(plank: plank) {
            let label = mill.rules.label(plank: plank);
            if first {
                result = label;
                first = false;
            } else {
                result = result.concat(other: ",").concat(other: label);
            }
        }
        i = i + 1;
    }
    result
}

