use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = herd.lineup();
    var output = "";
    var i = 0;
    while i < lineup.length() {
        let pony = lineup.get(index: i);
        herd.feed(pony: pony, scoops: 3);
        let entry = ledger.render(pony: pony);
        let entry_text = entry.to_text();
        if i == 0 {
            output = entry_text;
        } else {
            output = output.concat(other: ",").concat(other: entry_text);
        }
        i = i + 1;
    }
    io.write(text: output)?;
    return Ok(unit);
}

